  function N(id, t, cap, a, r, l, u, o){
    var n = { id: id, t: t, cap: cap, l: T(l[0], l[1]) };
    if (u) n.u = T(u[0], u[1]);
    if (a) n.a = a;
    if (r) n.r = r;
    if (o) {
      if (o.need) n.need = T(o.need[0], o.need[1]);
      if (o.out) n.out = T(o.out[0], o.out[1]);
      if (o.f) n.f = T(o.f[0], o.f[1]);
      if (o.s) n.s = T(o.s[0], o.s[1]);
      if (o.e) n.e = o.e;
      if (o.x) n.x = o.x;
    }
    return n;
  }

